ans = [r[:] for r in grid]
def panel_nonempty(rb, cb):
    return any(grid[rr][cc] != 0 for rr in range(rb, rb+5) for cc in range(cb, cb+5))
def reflect_right(rb, left_cb, right_cb):
    for dr in range(5):
        for dx in range(5):
            v = grid[rb+dr][left_cb+dx]
            if v:
                ans[rb+dr][right_cb+(4-dx)] = v
# Row band 1: mirror the two unmatched objects to the adjacent right panels.
reflect_right(6, 0, 6)
reflect_right(6, 12, 18)
# Bottom full band: the unmatched object in panel column 1 mirrors into column 2.
reflect_right(18, 6, 12)
assert len(ans)==26 and all(len(r)==23 for r in ans)
print('\n'.join('['+', '.join(map(str,r))+'],' for r in ans))

ans2 = [r[:] for r in ans]
# Replace the bottom-band copy: mirror panel column 1 into column 0 instead of column 2.
for dr in range(5):
    for dx in range(5):
        ans2[18+dr][4-dx] = grid[18+dr][6+dx]
print('\n'.join('['+', '.join(map(str,r))+'],' for r in ans2))

for rb, left_cb, right_cb in [(6,0,6),(6,12,18)]:
    for dy in range(5):
        for dx in range(5):
            v = grid[rb+dy][left_cb+dx]
            if v:
                final_grid[rb+dy][right_cb+4-dx] = v
assert len(final_grid)==26 and all(len(r)==23 for r in final_grid)
print('\n'.join('['+', '.join(map(str,r))+'],' for r in final_grid))
